def texts_are_unique(
    texts: List[str]
) -> bool:
    """Check a local set of strings."""
    # pylint: disable=all
    seen: Set[str] = set()
    for text in texts:
        if text in seen:
            return False
        seen.add(text)
    return True


def numbers_are_unique_between_zeros(
    numbers: List[int]
) -> bool:
    """Check a local set of integers which we reset at every zero."""
    # pylint: disable=all
    seen: Set[int] = set()
    for number in numbers:
        if number == 0:
            seen = set()
            continue
        if number in seen:
            return False
        seen.add(number)
    return True


