class _Transformer(
        aas_types.AbstractTransformer[
            Iterator[Error]
        ]
):
    # noinspection PyMethodMayBeStatic
    def transform_something(
            self,
            that: aas_types.Something
    ) -> Iterator[Error]:
        if not (
            that.optional_texts_are_unique_ignoring(aas_constants.RESERVED_TEXTS)
        ):
            yield Error(
                'Optional texts must be unique, apart from the reserved ones.'
            )

        if not (
            texts_are_disjoint(that.texts, that.optional_texts)
        ):
            yield Error(
                'Optional texts must not share any text with texts.'
            )

        if not (
            not is_in_kinds(that.kind, aas_constants.SPECIAL_KINDS)
        ):
            yield Error(
                'Kind must not be special.'
            )

        if not (
            not (len(that.numbers) in aas_constants.LUCKY_NUMBERS)
        ):
            yield Error(
                'Number of numbers must not be lucky.'
            )

        if not (not (that.number in aas_constants.LUCKY_NUMBERS)):
            yield Error(
                'Number must not be lucky.'
            )

        if not text_is_not_reserved(that.text):
            yield Error(
                'Text must not be reserved.'
            )

        if not lengths_are_unique(that.texts):
            yield Error(
                'Texts must be of unique lengths.'
            )

        if not flags_are_uniform(that.flags):
            yield Error(
                'Flags must be either all true or all false.'
            )

        if not codes_are_unique(that.codes):
            yield Error(
                'Codes must be unique.'
            )

        if not kinds_are_unique(that.kinds):
            yield Error(
                'Kinds must be unique.'
            )

        if not numbers_are_unique_between_zeros(that.numbers):
            yield Error(
                'Numbers must be unique between the zeros.'
            )

        if not (
            not (that.optional_kind is not None)
            or (not (that.optional_kind in aas_constants.SPECIAL_KINDS))
        ):
            yield Error(
                'Optional kind must not be special.'
            )

        if not (
            some_kind_is_not_special(
                that.kinds,
                that.optional_kind
            )
        ):
            yield Error(
                'Kinds and the optional kind, if any, must contain a kind ' +
                'which is not special.'
            )

        if not at_most_one_text_is_reserved(that.texts):
            yield Error(
                'At most one text must be reserved.'
            )

        if not numbers_are_all_small(that.numbers):
            yield Error(
                'Numbers must be smaller than 1000.'
            )

        if not unique_texts_are_all_short(that.texts):
            yield Error(
                'Texts must be at most 10 characters long.'
            )

        if not texts_are_unique(that.texts):
            yield Error(
                'Texts must be unique.'
            )

        for i, yet_yet_another_item in enumerate(that.codes):
            for error in verify_code(yet_yet_another_item):
                error.path._prepend(
                    IndexSegment(
                        that.codes,
                        i
                    )
                )
                error.path._prepend(
                    PropertySegment(
                        that,
                        'codes'
                    )
                )
                yield error


